import java.util.*;

class Solution {
    public TreeNode roundTrip(TreeNode root) {
        return deserialize(serialize(root));
    }

    private String serialize(TreeNode root) {
        StringBuilder sb = new StringBuilder();
        ser(root, sb);
        return sb.toString();
    }

    private void ser(TreeNode node, StringBuilder sb) {
        if (node == null) { sb.append("N,"); return; }
        sb.append(node.val).append(',');
        ser(node.left, sb);
        ser(node.right, sb);
    }

    private int di;

    private TreeNode deserialize(String data) {
        di = 0;
        return des(data.split(","));
    }

    private TreeNode des(String[] tokens) {
        String t = tokens[di++];
        if (t.equals("N")) return null;
        TreeNode node = new TreeNode(Integer.parseInt(t));
        node.left = des(tokens);
        node.right = des(tokens);
        return node;
    }
}
